query advisedStudentsQuery(
  $mnumber: String!
  $term_code: String!
  $year: Int!
) {
  studentAdvisors(where: {advisor_mnumber: {eq: $mnumber}, term_code: {eq: $term_code}, year: {eq: $year}}) {
    student {
      mnumber
      first_name
      middle_name
      last_name
      suffix
      email
      gender
    }
  }
}

